def calculate_row_value(c, i):
    # Rows R_i are indexed 1 to 16, columns c are indexed 1 to 16.
    # The formula is R_i(c) = ((c + i - 2) mod 16) + 1
    return ((c + i - 2) % 16) + 1

N = 16
C = 16
all_pairs_satisfied = True

# Iterate over all distinct pairs of rows (i, j)
for i in range(1, N + 1):
    for j in range(1, N + 1):
        if i == j:
            continue

        # Check if the condition (ii) is satisfied for the pair (i, j)
        condition_ii_satisfied = False
        for c in range(1, C + 1):
            Ri_c = calculate_row_value(c, i)
            Rj_c = calculate_row_value(c, j)

            if abs(Ri_c - Rj_c) >= 2:
                condition_ii_satisfied = True
                # print(f"Pair ({i}, {j}) satisfied at column {c}: |{Ri_c} - {Rj_c}| = {abs(Ri_c - Rj_c)}")
                break

        if not condition_ii_satisfied:
            all_pairs_satisfied = False
            print(f"Failure found for pair ({i}, {j}). No column c gives |R_i(c) - R_j(c)| >= 2.")
            break
    if not all_pairs_satisfied:
        break

if all_pairs_satisfied:
    print("SUCCESS: For all distinct pairs of rows (i, j), there exists at least one column c such that |R_i(c) - R_j(c)| >= 2.")
else:
    print("FAILURE: Not all pairs satisfied the condition.")
